-- Aviso nuevo: alguien de la cocina creó una materia prima desde una receta y falta completarla (ADR-0064). Va en su propia
-- migración: Postgres no deja usar un valor nuevo de un enum en la misma transacción que lo agrega.
alter type core.notification_kind add value 'ingredient_created';
comment on type core.notification_kind is
  'Tipo de aviso: approval_requested (pedido de aprobación), recipe_changed (cambió una preparación), recipe_cost_changed (cambió el costo de una receta, sin importes), yield_deviation (un ensayo de rendimiento se desvió del estándar más que el umbral), supplier_account_changed (cambió una cuenta de pago de un proveedor), unmapped_article (llegó un artículo de proveedor que el sistema no reconoce), price_list_expired (venció la lista de precios de un proveedor), order_news (novedad de una orden de compra), receipt_report y receipt_differences (informe y diferencias de una recepción), invoice_observed (una factura no pasó el control), price_variation (un precio de factura varió más que el umbral), payment_due (una factura vence en 7 días o venció: lo ve quien paga), account_changed (otra persona le cambió el nombre o le cerró las sesiones: lo ve en Mi cuenta) e ingredient_created (la cocina creó una materia prima desde una receta: la completa Compras).';
